// DERMA-SHIELD · Gradle settings
//
// `capacitor.settings.gradle` and the `capacitor-cordova-android-plugins`
// module are GENERATED by `npx cap sync android`. They are applied/included
// here because `app/capacitor.build.gradle` declares
// `implementation project(':capacitor-haptics')` — if this settings file did
// not apply the generated one, Gradle would fail with
// "Project with path ':capacitor-haptics' could not be found".
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}

include(":app")
include(":capacitor-cordova-android-plugins")
project(":capacitor-cordova-android-plugins").projectDir = file("./capacitor-cordova-android-plugins/")

apply(from = "capacitor.settings.gradle")
